}

.wallet-strip .coin-icon {
  width: 16px;
  height: 16px;
  border-width: 1.5px;
}

.shop-card {
  position: relative;
  display: flex;
  align-items: center;
  gap: 11px;
  margin-top: 9px;
  padding: 10px;
  overflow: hidden;
  border: 1px solid rgba(255, 240, 218, 0.1);
