  place-items: center;
  overflow: hidden;
  border: 1px solid rgba(244, 187, 85, 0.16);
  border-radius: 13px;
  background:
    radial-gradient(circle at 50% 40%, rgba(244, 187, 85, 0.16), transparent 55%),
    #241d25;
}

.shop-art svg {
  width: 66px;
  height: 66px;
}

.shop-copy {
  min-width: 0;
  flex: 1;
}

.shop-copy .tag {
  display: inline-block;
  margin-bottom: 3px;
  padding: 2px 5px;
  border: 1px solid rgba(195, 165, 113, 0.2);
  border-radius: 4px;
  color: #c6a977;
  font-size: 5.5px;
  font-weight: 900;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

.shop-copy h3 {
  margin: 0;
  color: #f4e6d1;
  font-family: var(--font-display);
  font-size: 17px;
  letter-spacing: -0.03em;
  line-height: 1;
}

.shop-copy p {
  margin: 4px 0 0;
  max-width: 195px;
  color: #a99ca4;
  font-size: 7.5px;
  font-weight: 600;
  line-height: 1.35;
}

.buy-btn {
  display: flex;
  min-width: 64px;
  flex: none;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 1px;
  align-self: stretch;
  border: 1px solid rgba(255, 228, 172, 0.4);
  border-radius: 12px;
  color: #39220c;
  background: linear-gradient(180deg, #ffe2a1, #efb452);
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.55);
  font-size: 12px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
  transition: transform 0.13s ease, filter 0.13s ease;
}

.buy-btn small {
  color: rgba(54, 31, 8, 0.57);
  font-size: 5.5px;
  font-weight: 900;
  letter-spacing: 0.09em;
  text-transform: uppercase;
}

.buy-btn:active:not(:disabled) {
  transform: scale(0.96);
  filter: brightness(1.08);
}

.buy-btn:disabled {
  border-color: rgba(255, 255, 255, 0.1);
  color: #8e827e;
  background: rgba(255, 255, 255, 0.06);
  box-shadow: none;
}

.buy-btn:disabled small { color: #71676e; }

.shop-collection {
  margin-top: 10px;
  padding: 9px 10px;
  border: 1px solid rgba(255, 255, 255, 0.07);
  border-radius: 13px;
  background: rgba(255, 255, 255, 0.022);
}

.collection-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #a99a9f;
  font-size: 6.5px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.collection-head span:last-child { color: #d7c3a0; }

.collection-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 3px;
  margin-top: 7px;
}

.collection-portrait {
  position: relative;
  width: 30px;
  height: 30px;
  overflow: hidden;
  border: 1px solid rgba(255, 240, 218, 0.14);
  border-radius: 50%;
  background: #201c26;
}

.collection-portrait .portrait {
  width: 100%;
  height: 100%;
  border: 0;
}

.collection-portrait.locked {
  filter: grayscale(1) brightness(0.6);
  opacity: 0.5;
}

.collection-portrait.locked::after {
  position: absolute;
  inset: 0;
  content: "";
  background: rgba(8, 7, 11, 0.2);
}

.shop-note {
  margin: 8px 2px 3px;
  color: #827784;
  font-size: 6.5px;
  font-weight: 700;
  line-height: 1.35;
  text-align: center;
}

.sheet-foot {
  flex: none;
  padding: 0 14px max(14px, calc(10px + var(--safe-bottom)));
}

/* ---------- Help ---------- */

.help-body {
  overflow-y: auto;
  overscroll-behavior: contain;
  padding: 0 16px 4px;
  scrollbar-width: none;
}

.help-body::-webkit-scrollbar { display: none; }

.how-step {
  display: flex;
  gap: 10px;
  margin-top: 9px;
  padding: 10px;
  border: 1px solid rgba(255, 255, 255, 0.075);
  border-radius: 14px;
  background: rgba(255, 255, 255, 0.025);
}

.step-num {
  display: grid;
  width: 30px;
  height: 30px;
  flex: none;
  place-items: center;
  border: 1px solid rgba(244, 187, 85, 0.27);
  border-radius: 9px;
  color: #f2c776;
  background: rgba(81, 59, 33, 0.3);
  font-family: var(--font-display);
  font-size: 17px;
}

.how-step strong {
  display: block;
  color: #ebdeca;
  font-size: 9px;
  font-weight: 900;
  letter-spacing: 0.03em;
  text-transform: uppercase;
}

.how-step p {
  margin: 3px 0 0;
  color: #a599a4;
  font-size: 7.5px;
  font-weight: 600;
  line-height: 1.45;
}

.help-foot {
  display: flex;
  gap: 8px;
  padding-top: 9px;
}

.help-foot .btn {
  flex: 1;
  height: 43px;
  border-radius: 12px;
  font-size: 9px;
}

.reset-btn {
  color: #c68d86;
  border-color: rgba(207, 111, 98, 0.23);
  background: rgba(139, 62, 58, 0.12);
}

/* ---------- Chest ---------- */

.chest-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 16px;
  background:
    radial-gradient(circle at 50% 42%, rgba(99, 66, 33, 0.5), transparent 37%),
    rgba(8, 7, 11, 0.9);
  pointer-events: auto;
  animation: overlay-in 0.3s ease-out both;
}

.chest-rays {
  position: absolute;
  top: 42%;
  left: 50%;
  width: 580px;
  height: 580px;
  border-radius: 50%;
  background: repeating-conic-gradient(from 8deg, rgba(255, 208, 105, 0.16) 0 5deg, transparent 5deg 18deg);
  opacity: 0;
  pointer-events: none;
  transform: translate(-50%, -50%) scale(0.6);
  -webkit-mask: radial-gradient(circle, transparent 16%, #000 38%, transparent 71%);
  mask: radial-gradient(circle, transparent 16%, #000 38%, transparent 71%);
  transition: opacity 0.55s ease, transform 1.1s cubic-bezier(0.2, 0.8, 0.2, 1);
}

.chest-overlay.lit .chest-rays {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1) rotate(8deg);
  animation: rays-spin 18s linear infinite;
}

@keyframes rays-spin {
  to { transform: translate(-50%, -50%) scale(1) rotate(368deg); }
}

.chest-panel {
  position: relative;
  z-index: 2;
  display: flex;
  width: min(100%, 420px);
  align-items: center;
  flex-direction: column;
  text-align: center;
}

.chest-stage {
  position: relative;
  width: min(64vw, 250px);
  margin-bottom: 2px;
  filter: drop-shadow(0 18px 30px rgba(0, 0, 0, 0.45));
}

.chest-stage svg {
  width: 100%;
  height: auto;
}

.chest-svg .lid {
  transform-box: view-box;
  transform-origin: 120px 99px;
  transition: transform 0.7s cubic-bezier(0.22, 1.1, 0.36, 1);
}

.chest-overlay.opened .chest-svg .lid {
  transform: rotate(-108deg) translateY(-2px);
}

.chest-stage::after {
  position: absolute;
  right: 14%;
  bottom: -8px;
  left: 14%;
  height: 18px;
  border-radius: 50%;
  background: rgba(0, 0, 0, 0.4);
  filter: blur(7px);
  content: "";
}

.chest-overlay.opening .chest-stage {
  animation: chest-shake 0.68s ease-in-out infinite;
}

@keyframes chest-shake {
  0%, 100% { transform: rotate(0) translateY(0); }
  14% { transform: rotate(-1.8deg) translateY(-2px); }
  28% { transform: rotate(1.8deg) translateY(1px); }
  42% { transform: rotate(-1.2deg) translateY(-1px); }
  56% { transform: rotate(1.2deg) translateY(0); }
}

.chest-glow {
  position: absolute;
  z-index: -1;
  top: 38%;
  left: 50%;
  width: 230px;
  height: 230px;
  border-radius: 50%;
  background: radial-gradient(circle, rgba(255, 215, 119, 0.62), transparent 63%);
  opacity: 0;
  transform: translate(-50%, -50%) scale(0.45);
  transition: opacity 0.4s ease, transform 0.7s ease;
}

.chest-overlay.opened .chest-glow {
  opacity: 1;
  transform: translate(-50%, -50%) scale(1.18);
}

.chest-copy {
  position: relative;
  z-index: 3;
  margin-top: 4px;
}

.chest-copy .eyebrow {
  color: #c7a364;
}

.chest-copy h2 {
  margin: 5px 0 0;
  color: #ffebc6;
  font-family: var(--font-display);
  font-size: 27px;
  font-weight: 700;
  letter-spacing: -0.045em;
  line-height: 1;
}

.chest-copy p {
  margin: 6px 0 0;
  color: #aa9a96;
  font-size: 8px;
  font-weight: 600;
}

.chest-cta {
  width: min(76vw, 225px);
  height: 50px;
  margin-top: 14px;
}

.chest-result {
  position: relative;
  z-index: 5;
  display: flex;
  width: min(100%, 360px);
  align-items: center;
  flex-direction: column;
  opacity: 0;
  pointer-events: none;
  transform: translateY(12px) scale(0.96);
  transition: opacity 0.4s ease, transform 0.4s ease;
}

.chest-result.show {
  opacity: 1;
  pointer-events: auto;
  transform: none;
}

.reveal-card {
  position: relative;
  display: flex;
  width: 100%;
  align-items: center;
  gap: 13px;
  padding: 13px;
  border: 1px solid rgba(255, 226, 164, 0.28);
  border-radius: 19px;
  background:
    radial-gradient(circle at 15% 25%, rgba(244, 187, 85, 0.17), transparent 36%),
    linear-gradient(135deg, rgba(61, 49, 54, 0.98), rgba(28, 24, 33, 0.98));
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.4), inset 0 1px rgba(255, 255, 255, 0.07);
  text-align: left;
}

.reveal-card.coins {
  background:
    radial-gradient(circle at 15% 25%, rgba(244, 187, 85, 0.22), transparent 40%),
    linear-gradient(135deg, rgba(58, 46, 37, 0.98), rgba(29, 24, 28, 0.98));
}

.reveal-portrait {
  position: relative;
  display: grid;
  width: 68px;
  height: 68px;
  flex: none;
  place-items: center;
  border: 2px solid var(--rarity, #f4bb55);
  border-radius: 50%;
  background: #32293a;
  box-shadow: 0 0 23px rgba(244, 187, 85, 0.19);
}

.reveal-portrait .portrait {
  width: 100%;
  height: 100%;
  border: 0;
}

.reveal-portrait .big-coin {
  width: 48px;
  height: 48px;
  border: 3px solid #ffe39b;
  border-radius: 50%;
  background: radial-gradient(circle at 34% 25%, #fff0ae, #e8b049 51%, #a66520 100%);
  box-shadow: inset 0 0 0 3px rgba(123, 67, 16, 0.2), 0 0 18px rgba(244, 187, 85, 0.35);
}

.reveal-copy {
  min-width: 0;
  flex: 1;
}

.reveal-copy .eyebrow {
  color: #c8a668;
}

.reveal-copy h3 {
  margin: 3px 0 0;
  color: #fff0d4;
  font-family: var(--font-display);
  font-size: 24px;
  letter-spacing: -0.04em;
  line-height: 0.95;
}

.reveal-copy .reveal-role {
  display: inline-block;
  margin-top: 4px;
  padding: 2px 5px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 4px;
  color: #b8aace;
  font-size: 5.5px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.reveal-copy p {
  margin: 5px 0 0;
  color: #a99ba2;
  font-size: 7px;
  font-weight: 600;
  line-height: 1.35;
}

.result-actions {
  display: flex;
  width: 100%;
  gap: 8px;
  margin-top: 12px;
}

.result-actions .btn {
  flex: 1;
  height: 48px;
  border-radius: 13px;
  font-size: 9px;
}

.confetti {
  position: absolute;
  z-index: 8;
  top: 50%;
  left: 50%;
  width: 7px;
  height: 11px;
  border-radius: 2px;
  pointer-events: none;
  animation: confetti-flight 1.2s cubic-bezier(0.15, 0.7, 0.35, 1) both;
}

@keyframes confetti-flight {
  0% { opacity: 1; transform: translate(-50%, -50%) rotate(0) scale(0.5); }
  100% { opacity: 0; transform: translate(calc(-50% + var(--dx)), calc(-50% + var(--dy))) rotate(var(--rot)) scale(1); }
}

/* ---------- Result ---------- */

.result-overlay {
  position: absolute;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  padding: 18px;
  background: rgba(7, 6, 10, 0.78);
  backdrop-filter: blur(7px);
  pointer-events: auto;
  animation: overlay-in 0.35s ease-out both;
}

.result-overlay::before {
  position: absolute;
  top: 38%;
  left: 50%;
  width: 580px;
  height: 580px;
  border-radius: 50%;
  background: repeating-conic-gradient(from 0deg, rgba(255, 211, 116, 0.11) 0 4deg, transparent 4deg 19deg);
  content: "";
  opacity: 0.8;
  -webkit-mask: radial-gradient(circle, transparent 23%, #000 50%, transparent 73%);
  mask: radial-gradient(circle, transparent 23%, #000 50%, transparent 73%);
  transform: translate(-50%, -50%);
  animation: rays-spin 26s linear infinite;
}

.result-overlay.loss::before {
  background: repeating-conic-gradient(from 0deg, rgba(203, 101, 87, 0.1) 0 4deg, transparent 4deg 20deg);
}

.result-card {
  position: relative;
  z-index: 2;
  width: min(100%, 370px);
  padding: 18px 16px 15px;
  border: 1px solid rgba(255, 231, 185, 0.24);
  border-radius: 24px;
  background:
    radial-gradient(circle at 50% 0%, rgba(122, 82, 38, 0.26), transparent 31%),
    linear-gradient(180deg, #2d2735, #191622);
  box-shadow: 0 22px 55px rgba(0, 0, 0, 0.48), inset 0 1px rgba(255, 255, 255, 0.09);
  text-align: center;
  animation: result-in 0.48s cubic-bezier(0.22, 1.2, 0.38, 1) both;
}

@keyframes result-in {
  from { opacity: 0; transform: translateY(20px) scale(0.92); }
  to { opacity: 1; transform: none; }
}

.result-emblem {
  display: grid;
  width: 62px;
  height: 62px;
  margin: -5px auto 9px;
  place-items: center;
  border: 1px solid rgba(244, 187, 85, 0.36);
  border-radius: 50%;
  color: #f6c668;
  background: radial-gradient(circle, rgba(130, 88, 40, 0.48), rgba(44, 34, 39, 0.8));
  box-shadow: 0 0 30px rgba(244, 187, 85, 0.17);
}

.result-emblem svg {
  width: 36px;
  height: 36px;
}

.result-overlay.loss .result-emblem {
  border-color: rgba(207, 104, 90, 0.3);
  color: #d98e7d;
  background: radial-gradient(circle, rgba(100, 46, 44, 0.45), rgba(34, 25, 29, 0.8));
  box-shadow: 0 0 30px rgba(207, 104, 90, 0.12);
}

.result-card .eyebrow { color: #bd9f6d; }
.result-overlay.loss .result-card .eyebrow { color: #b78a7d; }

.result-card h2 {
  margin: 5px 0 0;
  color: #ffedce;
  font-family: var(--font-display);
  font-size: 36px;
  font-weight: 700;
  letter-spacing: -0.055em;
  line-height: 0.9;
}

.result-card .result-sub {
  margin: 7px auto 0;
  max-width: 260px;
  color: #a79a9f;
  font-size: 8px;
  font-weight: 600;
  line-height: 1.45;
}

.loot-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 7px;
  margin-top: 12px;
}

.loot-cell {
  padding: 8px 5px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 11px;
  background: rgba(255, 255, 255, 0.035);
}

.loot-cell span {
  display: block;
  color: #8e8290;
  font-size: 6px;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

.loot-cell strong {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
  margin-top: 3px;
  color: #ffe09b;
  font-size: 17px;
  font-weight: 900;
  font-variant-numeric: tabular-nums;
}

.loot-cell strong .coin-icon {
  width: 16px;
  height: 16px;
  border-width: 1.5px;
}

.loot-cell.xp strong { color: #a8d7b9; }

.depth-unlock {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 6px;
  margin-top: 9px;
  padding: 7px;
  border: 1px solid rgba(139, 201, 168, 0.17);
  border-radius: 10px;
  color: #a8cfb3;
  background: rgba(89, 140, 110, 0.07);
  font-size: 7px;
  font-weight: 900;
  letter-spacing: 0.07em;
  text-transform: uppercase;
}

.depth-unlock strong { color: #d3eeda; }

.level-ups {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 4px;
  margin-top: 7px;
}

.level-up-pill {
  padding: 3px 7px;
  border: 1px solid rgba(244, 187, 85, 0.24);
  border-radius: 999px;
  color: #eecb82;
  background: rgba(244, 187, 85, 0.075);
  font-size: 6.5px;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

.result-card .btn {
  width: 100%;
  height: 51px;
  margin-top: 12px;
}

/* ---------- Toast ---------- */

.toast-root {
  position: absolute;
  z-index: 120;
  right: 0;
  bottom: 90px;
  left: 0;
  display: flex;
  align-items: center;
  flex-direction: column;
  gap: 6px;
  pointer-events: none;
}

.toast {
  max-width: calc(100% - 36px);
  padding: 8px 13px;
  border: 1px solid rgba(255, 236, 202, 0.16);
  border-radius: 999px;
  color: #efe1cc;
  background: rgba(34, 29, 41, 0.94);
  box-shadow: 0 8px 20px rgba(0, 0, 0, 0.32);
  font-size: 8px;
  font-weight: 800;
  letter-spacing: 0.015em;
  text-align: center;
  animation: toast-in 0.3s ease-out both;
  backdrop-filter: blur(8px);
}

.toast.warn {
  border-color: rgba(224, 143, 96, 0.31);
  color: #f2c3a6;
}

.toast.good {
  border-color: rgba(139, 201, 168, 0.3);
  color: #bfe2c9;
}

.toast.out {
  animation: toast-out 0.24s ease-in both;
}

@keyframes toast-in {
  from { opacity: 0; transform: translateY(8px) scale(0.96); }
  to { opacity: 1; transform: none; }
}

@keyframes toast-out {
  to { opacity: 0; transform: translateY(-4px) scale(0.98); }
}

.drag-root {
  position: absolute;
  z-index: 150;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
}

/* ---------- Descent transition ---------- */

.descent-veil {
  position: absolute;
  z-index: 45;
  inset: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-direction: column;
  overflow: hidden;
  background:
    radial-gradient(circle at 50% 24%, rgba(241, 191, 109, 0.18), transparent 22%),
    #0c1013;
  animation: veil-in 0.22s ease-out both;
  pointer-events: auto;
}

.descent-veil::before {
  position: absolute;
  inset: -50% 0;
  background: repeating-linear-gradient(90deg, transparent 0 39px, rgba(169, 188, 167, 0.08) 39px 40px);
  content: "";
  animation: shaft-rush 0.7s linear infinite;
}

@keyframes veil-in {
  from { opacity: 0; }
  to { opacity: 1; }
}

@keyframes shaft-rush {
  from { transform: translateY(0); }
  to { transform: translateY(48px); }
}

.descent-cart {
  position: relative;
  z-index: 2;
  display: grid;
  width: 72px;
  height: 54px;
  place-items: center;
