/* ---------- Cave ---------- */

.cave {
  background:
    radial-gradient(circle at 50% 40%, rgba(62, 102, 93, 0.17), transparent 47%),
    #0e1418;
}

.cave-head {
  display: flex;
  min-height: 48px;
  flex: none;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  padding: 5px 12px 6px;
}

.cave-back {
  display: flex;
  height: 32px;
  align-items: center;
  gap: 4px;
  padding: 0 9px 0 6px;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 10px;
  color: #bcb1c2;
  background: rgba(255, 255, 255, 0.035);
  font-size: 7.5px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cave-back:active { transform: scale(0.96); }

.cave-back svg {
  width: 13px;
  height: 13px;
}

.depth-badge {
  display: flex;
  height: 34px;
  align-items: center;
  gap: 7px;
  padding: 0 11px;
  border: 1px solid rgba(244, 187, 85, 0.3);
  border-radius: 11px;
  color: #f2cf89;
  background: linear-gradient(180deg, rgba(105, 76, 43, 0.34), rgba(40, 32, 34, 0.64));
  box-shadow: inset 0 1px rgba(255, 255, 255, 0.05);
}

.depth-badge small {
  color: #a58a66;
  font-size: 6.5px;
  font-weight: 900;
  letter-spacing: 0.16em;
}

.depth-badge strong {
  font-family: var(--font-display);
  font-size: 16px;
  line-height: 1;
}

.cave-threat {
  display: flex;
  height: 32px;
  align-items: center;
  gap: 5px;
  padding: 0 8px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 10px;
  color: #a99c8b;
  background: rgba(255, 255, 255, 0.03);
  font-size: 6.5px;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.cave-world {
  position: relative;
  flex: 1;
  min-height: 0;
  margin: 0 10px;
  overflow: hidden;
  border: 1px solid rgba(255, 237, 207, 0.08);
  border-radius: 20px;
  background: #11191b;
  box-shadow: inset 0 0 60px rgba(0, 0, 0, 0.42);
}

.cave-art {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.cave-world::after {
  position: absolute;
  inset: 0;
  background:
