.screen {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  animation: screen-in 0.36s cubic-bezier(0.22, 0.8, 0.25, 1) both;
}

@keyframes screen-in {
  from { transform: translateY(12px) scale(0.988); }
  to { transform: none; }
}

.screen.no-enter {
  animation: none;
}

.stage-ghost {
  position: absolute;
  z-index: 6;
  inset: 0;
  overflow: hidden;
  pointer-events: none;
  animation: ghost-out 0.34s ease-out both;
}

@keyframes ghost-out {
  from { opacity: 1; }
  to { opacity: 0; }
}

