```js
function stepWalk(unit, dt) {
  const walk = unit.walk;
  if (!walk) return;
  const dx = walk.tx - unit.x;
  const dy = walk.ty - unit.y;
  const dist = Math.hypot(dx, dy);
  const step = unit.speed * dt;
  if (dist <= step || dist < 0.8) {
    unit.x = walk.tx; unit.y = walk.ty;
    const done = walk.done; stopWalking(unit);
    applyUnitPos(unit);
    done?.();
    return;
  }
  unit.x += (dx / dist) * step;
  unit.y += (dy / dist) * step;
  applyUnitPos(unit);
}

function applyUnitPos(unit) {
  unit.el?.style.setProperty('--x', unit.x.toFixed(2));
  unit.el?.style.setProperty('--y', unit.y.toFixed(2));
}
