/* CDP driver: load the game, click through flows, save screenshots. */
const fs = require('fs');
const path = require('path');

const OUT = '/tmp/opencode/shots';
fs.mkdirSync(OUT, { recursive: true });

const CDP_PORT = process.env.CDP_PORT || '9222';
const URL_BASE = process.env.GAME_URL || 'http://127.0.0.1:3003/index.html';
const W = parseInt(process.env.SHOT_W || '390', 10);
const H = parseInt(process.env.SHOT_H || '844', 10');

let ws;
let msgId = 0;
const pending = new Map();

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

async function waitLoad() {
  return new Promise(resolve => {
    const handler = data => {
      const msg = JSON.parse(data);
      if (msg.method === 'Page.loadEventFired') {
        ws.removeEventListener('message', handler);
        resolve();
      }
    };
    ws.addEventListener('message', handler);
  });
}

function sleep(ms) {
  return new Promise(r => setTimeout(r, ms));
}

async function evalJs(expression) {
  const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (res.exceptionDetails) {
    console.error('EVAL ERROR:', JSON.stringify(res.exceptionDetails).slice(0, 400));
  }
  return res.result?.value;
}

async function shot(name) {
  const data = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(OUT, `${name}.png`), Buffer.from(data.data, 'base64'));
  console.log('shot:', name);
}

async function click(selector) {
  await evalJs(`(() => { const el = document.querySelector(${JSON.stringify(selector)}); if (!el) return 'missing:' + ${JSON.stringify(selector)}; el.click(); return 'ok'; })()`);
}

async function main() {
  const listRes = await fetch(`http://127.0.0.1:${CDP_PORT}/json`);
  const targets = await listRes.json();
  const page = targets.find(t => t.type === 'page');
  ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

  ws.addEventListener('message', data => {
    const msg = JSON.parse(data.data);
    if (msg.id && pending.has(msg.id)) {
      const { resolve } = pending.get(msg.id);
      pending.delete(msg.id);
      resolve(msg.result || {});
    } else if (msg.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(msg.params.type)) {
      console.log('CONSOLE', msg.params.type, msg.params.args.map(a => a.value ?? a.description).join(' ').slice(0, 300));
    } else if (msg.method === 'Runtime.exceptionThrown') {
      console.log('PAGE EXCEPTION:', msg.params.exceptionDetails.exception?.description?.slice(0, 300));
    }
  });

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 2, mobile: true });
  await send('Emulation.setTouchEmulationEnabled', { enabled: true });

  // fresh save
  const loaded = waitLoad();
  await send('Page.navigate', { url: URL_BASE });
  await loaded;
  await evalJs('localStorage.clear(); true;');
  const loaded2 = waitLoad();
  await send('Page.navigate', { url: URL_BASE });
  await loaded2;
  await sleep(700);

  const script = process.env.FLOW || 'full';

  if (script === 'full') {
    await sleep(400);
    await shot('01-surface');

    // equip two heroes
    await click('[data-equip="pip"]');
    await sleep(500);
    await click('[data-equip="nyx"]');
    await sleep(500);
    await shot('02-surface-equipped');

    // descend
    await click('[data-action="descend"]');
    await sleep(700);
    await shot('03-cave');

    // deploy pip then nyx
    await click('[data-cart-hero="pip"]');
    await sleep(300);
    await click('[data-pad="0"]');
    await sleep(400);
    await click('[data-cart-hero="nyx"]');
    await sleep(300);
    await click('[data-pad="1"]');
    await sleep(400);
    await shot('04-cave-deployed');

    // fight
    await click('[data-action="fight"]');
    await sleep(1000);
    await shot('05-battle-start');
    await sleep(1500);
    await shot('06-battle-mid');
    await sleep(2000);
    await shot('07-battle-later');
    await sleep(2500);
    await shot('08-battle-end');
    await sleep(3000);
    await shot('09-after');
  }

  if (script === 'desktop') {
    await send('Emulation.clearDeviceMetricsOverride');
    await send('Emulation.setDeviceMetricsOverride', { width: 1280, height: 760, deviceScaleFactor: 1, mobile: false });
    await sleep(500);
    await shot('d1-surface');
    await click('[data-equip="pip"]');
    await sleep(400);
    await click('[data-equip="bram"]');
    await sleep(400);
    await click('[data-action="descend"]');
    await sleep(700);
    await click('[data-cart-hero="pip"]');
    await sleep(250);
    await click('[data-pad="0"]');
    await sleep(350);
    await click('[data-cart-hero="bram"]');
    await sleep(250);
    await click('[data-pad="1"]');
    await sleep(350);
    await click('[data-action="fight"]');
    await sleep(1600);
    await shot('d2-battle');
    await sleep(2500);
    await shot('d3-battle-later');
  }

  if (script === 'narrow') {
    await send('Emulation.clearDeviceMetricsOverride');
    await send('Emulation.setDeviceMetricsOverride', { width: 320, height: 568, deviceScaleFactor: 2, mobile: true });
    await sleep(400);
    await shot('n1-surface');
    await click('[data-equip="pip"]');
    await sleep(400);
    await click('[data-action="descend"]');
    await sleep(600);
    await click('[data-cart-hero="pip"]');
    await sleep(250);
    await click('[data-pad="0"]');
    await sleep(300);
    await click('[data-action="fight"]');
    await sleep(1600);
    await shot('n2-battle');
    await sleep(2200);
    await shot('n3-battle-later');
  }

  console.log('done');
  process.exit(0);
}

main().catch(err => { console.error('FATAL', err); process.exit(1); });

