/* Burst mode: fight, then rapid screenshots to observe walking/striking. */
process.env.FLOW = 'burst';
const fs = require('fs');
const path = require('path');

const OUT = '/tmp/opencode/shots';
const CDP_PORT = '9222';
const URL_BASE = 'http://127.0.0.1:3003/index.html';

let ws;
let msgId = 0;
const pending = new Map();

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

function waitLoad() {
  return new Promise(resolve => {
    const handler = ev => {
      let msg;
      try { msg = JSON.parse(typeof ev.data === 'string' ? ev.data : ev); } catch { return; }
      if (msg.method === 'Page.loadEventFired') {
        ws.removeEventListener('message', handler);
        resolve();
      }
    };
    ws.addEventListener('message', handler);
  });
}

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function evalJs(expression) {
  const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (res.exceptionDetails) console.error('EVAL ERROR:', JSON.stringify(res.exceptionDetails).slice(0, 300));
  return res.result?.value;
}

async function shot(name) {
  const data = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(OUT, `${name}.png`), Buffer.from(data.data, 'base64'));
}

async function click(selector) {
  const res = await evalJs(`(() => { const el = document.querySelector(${JSON.stringify(selector)}); if (!el) return 'missing:' + ${JSON.stringify(selector)}; if (el.disabled) return 'disabled:' + ${JSON.stringify(selector)}; el.click(); return 'ok'; })()`);
  console.log('click', selector, '->', res);
}

async function main() {
  const targets = await (await fetch(`http://127.0.0.1:${CDP_PORT}/json`)).json();
  const page = targets.find(t => t.type === 'page');
  ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  ws.addEventListener('message', data => {
    let msg;
    try { msg = JSON.parse(typeof data.data === 'string' ? data.data : data); } catch { return; }
    if (msg.id && pending.has(msg.id)) {
      const { resolve } = pending.get(msg.id);
      pending.delete(msg.id);
      resolve(msg.result || {});
    } else if (msg.method === 'Runtime.exceptionThrown') {
      console.log('PAGE EXCEPTION:', msg.params.exceptionDetails.exception?.description?.slice(0, 300));
    }
  });

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: 390, height: 844, deviceScaleFactor: 2, mobile: true });

  const loaded = waitLoad();
  await send('Page.navigate', { url: URL_BASE.replace(/index\.html.*$/, 'nope-404') });
  await loaded;
  await evalJs('localStorage.clear(); "cleared"');
  const loaded2 = waitLoad();
  await send('Page.navigate', { url: URL_BASE });
  await loaded2;
  await sleep(600);

  await click('[data-equip="pip"]');
  await sleep(300);
  await click('[data-equip="nyx"]');
  await sleep(300);
  await click('[data-action="descend"]');
  await sleep(500);
  await click('[data-cart-hero="pip"]');
  await sleep(200);
  await click('[data-pad="0"]');
  await sleep(300);
  await click('[data-cart-hero="nyx"]');
  await sleep(200);
  await click('[data-pad="1"]');
  await sleep(300);
  await click('[data-action="fight"]');

  for (let i = 1; i <= 10; i++) {
    await sleep(450);
    await shot(`b${String(i).padStart(2, '0')}`);
  }
  console.log('burst done');
  process.exit(0);
}

main().catch(err => { console.error('FATAL', err); process.exit(1); });

