async function freshPage(seed) {
  // Clear (and optionally seed) storage on a URL with no game code so the
  // beforeunload save can't resurrect old state.
  const loaded = waitLoad();
  await send('Page.navigate', { url: URL_BASE.replace(/index\.html.*$/, 'nope-404') });
