      unit.wt = null;
      unit.el?.classList.remove('walking');
      syncUnitPoint(unit);
      if (walk.cb) walk.cb();
      return;
    }
    unit.x += dx / dist * step;
    unit.y += dy / dist * step;
    syncUnitPoint(unit);
  }

  /* Keep a melee fighter planted at their clash spot. Returns true once they
     are in position and free to swing. */
  function holdPosition(unit, target) {
    const spot = engagementPoint(unit, target);
    const spotChanged = unit.engX == null ||
      unit.targetUidSpot !== target.uid ||
      Math.abs(spot.x - unit.engX) > 0.5 ||
      Math.abs(spot.y - unit.engY) > 0.5;
    if (spotChanged) {
      unit.targetUidSpot = target.uid;
      unit.engX = spot.x;
      unit.engY = spot.y;
      walkUnit(unit, spot.x, spot.y);
      return false;
    }
    if (!unit.wt && (Math.abs(unit.x - unit.engX) > 1.2 || Math.abs(unit.y - unit.engY) > 1.2)) {
      walkUnit(unit, unit.engX, unit.engY);
      return false;
    }
    return !unit.wt;
  }

'''
