'''
src = src[:start] + new_strike + src[end:]

# ------------------------------------------------------------------ hero + enemy attacks
start = src.index('  function heroAttack(hero, targets) {')
end = src.index('  function damageEnemy(enemy, amount, crit = false) {')
new_attacks = '''  function heroAttack(hero, target) {
    if (!target || !target.alive) return;
    const crit = Math.random() < 0.12;
    const damage = hero.atk * rand(0.9, 1.1) * (crit ? 1.68 : 1);

    if (isRangedUnit(hero)) {
