/* CDP driver: verify real-time battle, new portraits and enemy art. */
const fs = require('fs');
const path = require('path');

const OUT = '/tmp/opencode/shots';
fs.mkdirSync(OUT, { recursive: true });

const CDP_PORT = process.env.CDP_PORT || '9222';
const URL_BASE = process.env.GAME_URL || 'http://127.0.0.1:3003/index.html';
const W = parseInt(process.env.SHOT_W || '390', 10);
const H = parseInt(process.env.SHOT_H || '844', 10);

let ws;
let msgId = 0;
const pending = new Map();

function send(method, params = {}) {
  return new Promise((resolve, reject) => {
    const id = ++msgId;
    pending.set(id, { resolve, reject });
    ws.send(JSON.stringify({ id, method, params }));
  });
}

function waitLoad() {
  return new Promise(resolve => {
    const handler = ev => {
      let msg;
      try { msg = JSON.parse(typeof ev.data === 'string' ? ev.data : ev); } catch { return; }
      if (msg.method === 'Page.loadEventFired') {
        ws.removeEventListener('message', handler);
        resolve();
      }
    };
    ws.addEventListener('message', handler);
  });
}

const sleep = ms => new Promise(r => setTimeout(r, ms));

async function evalJs(expression) {
  const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (res.exceptionDetails) {
    console.error('EVAL ERROR:', JSON.stringify(res.exceptionDetails).slice(0, 400));
  }
  return res.result?.value;
}

async function shot(name) {
  const data = await send('Page.captureScreenshot', { format: 'png' });
  fs.writeFileSync(path.join(OUT, `${name}.png`), Buffer.from(data.data, 'base64'));
  console.log('shot:', name);
}

async function click(selector) {
  const res = await evalJs(`(() => { const el = document.querySelector(${JSON.stringify(selector)}); if (!el) return 'missing'; if (el.disabled) return 'disabled'; el.click(); return 'ok'; })()`);
  console.log('click', selector, '->', res);
}

async function freshPage(seed) {
  const loaded = waitLoad();
  await send('Page.navigate', { url: URL_BASE.replace(/index\.html.*$/, 'nope-404') });
  await loaded;
  const clearExpr = seed
    ? `localStorage.clear(); localStorage.setItem('downbound.save.v2', ${JSON.stringify(JSON.stringify(seed))}); 'seeded'`
    : 'localStorage.clear(); "cleared"';
  await evalJs(clearExpr);
  const loaded2 = waitLoad();
  await send('Page.navigate', { url: URL_BASE });
  await loaded2;
}

const probeExpr = `JSON.stringify([...document.querySelectorAll('.battle-unit')].map(el => {
  const cs = getComputedStyle(el);
  const hp = el.querySelector('.unit-health i');
  return {
    who: (el.dataset.battleHero ? 'h:' : 'e:') + (el.dataset.uid || ''),
    x: Number(cs.getPropertyValue('--x')),
    y: Number(cs.getPropertyValue('--y')),
    hp: Math.round(parseFloat(hp?.style.width || '100')),
    dead: el.classList.contains('dead') || el.classList.contains('dying'),
    cls: el.className
  };
}))`;

async function main() {
  const listRes = await fetch(`http://127.0.0.1:${CDP_PORT}/json`);
  const targets = await listRes.json();
  const page = targets.find(t => t.type === 'page');
  ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

  ws.addEventListener('message', data => {
    let msg;
    try { msg = JSON.parse(typeof data.data === 'string' ? data.data : data); } catch { return; }
    if (msg.id && pending.has(msg.id)) {
      const { resolve } = pending.get(msg.id);
      pending.delete(msg.id);
      resolve(msg.result || {});
    } else if (msg.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(msg.params.type)) {
      console.log('CONSOLE', msg.params.type, msg.params.args.map(a => a.value ?? a.description).join(' ').slice(0, 300));
    } else if (msg.method === 'Runtime.exceptionThrown') {
      console.log('PAGE EXCEPTION:', msg.params.exceptionDetails.exception?.description?.slice(0, 300));
    }
  });

  await send('Page.enable');
  await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 2, mobile: true });
  await send('Emulation.setTouchEmulationEnabled', { enabled: true });

  const allHeroes = ['pip', 'nyx', 'bram', 'mica', 'sable', 'flint', 'wren', 'orin'];
  const levels = {}; const xp = {};
  allHeroes.forEach(id => { levels[id] = 12; xp[id] = 0; });
  await freshPage({
    version: 2, coins: 4800, slots: 5, heroes: allHeroes, levels, xp,
    cart: ['pip', 'nyx', 'bram', 'mica', 'sable'],
    depth: 10, bestDepth: 12, wins: 32, chests: 2, sound: false
  });
  await sleep(900);
  await shot('r1-surface-bubbles');

  // shop shows hero cards with the rebuilt bubbles
  await click('[data-action="shop"]');
  await sleep(800);
  await shot('r2-shop-bubbles');
  await click('#shopCloseBtn');
  await sleep(700);

  await click('[data-action="descend"]');
  await sleep(900);
  await shot('r3-cave-bubbles');

  // make sure five fighters are deployed
  const pads = await evalJs(`JSON.stringify([...document.querySelectorAll('.deploy-pad')].map(p => p.dataset.pad + ':' + (p.dataset.cartHero || p.querySelector('.portrait')?.dataset.hero || '')))`);
  console.log('pads:', pads);

  await click('[data-action="fight"]');
  await sleep(120);
  await shot('r4-fight-banner');
  await sleep(800);
  await shot('r5-charge');
  await sleep(600);
  await shot('r6-clash');
  await sleep(500);
  await shot('r7-clash2');

  console.log('--- movement probe ---');
  for (let i = 0; i < 10; i++) {
    await sleep(420);
    console.log(i, await evalJs(probeExpr));
    if (i === 3) await shot('r8-scrum');
  }
  await sleep(1200);
  await shot('r9-fighting');

  // wait for result
  for (let i = 0; i < 40; i++) {
    const hasResult = await evalJs(`Boolean(document.querySelector('.result-overlay'))`);
    if (hasResult) break;
    await sleep(500);
  }
  await shot('r10-result');
  console.log('result text:', await evalJs(`document.querySelector('.result-card')?.innerText?.slice(0, 160) || 'none'`));

  const errors = await evalJs(`JSON.stringify({ screens: [...document.querySelectorAll('.screen')].map(s => s.className), overlay: document.querySelector('#overlayRoot')?.className, units: document.querySelectorAll('.battle-unit').length })`);
  console.log('DIAG:', errors);
  console.log('done');
  process.exit(0);
}

main().catch(err => { console.error('FATAL', err); process.exit(1); });

