  const rect = arena.getBoundingClientRect();
  const aspect = rect.width / Math.max(1, rect.height);
  const floorTop = clamp(0.5 + 0.26 * aspect, 0.52, 0.9);
  const floorBottom = 97;
  const apply = (unit, fx, fd) => {
