#!/usr/bin/env python3
"""Start every brawl already joined: pre-place fighters at their duel spots."""
PATH = 'js/game.js'
src = open(PATH).read()

# ------------------------------------------------------- pair + pre-place helper
start = src.index('  function acquireTarget(unit) {')
end = src.index('  function syncUnitPoint(unit) {')
pair_helper = '''  function acquireTarget(unit) {
    if (!battle) return null;
    const pool = (unit.key ? battle.heroes : battle.enemies).filter(other => other.alive);
    if (!pool.length) return null;
    const current = pool.find(other => other.uid === unit.targetUid);
    if (current) return current;
    // Slot pairing gives both sides matching opponents, so duels stay mutual.
    const sorted = [...pool].sort((a, b) => a.slot - b.slot);
    const target = sorted[unit.slot % sorted.length];
    unit.targetUid = target.uid;
    return target;
  }

  /* The brawl starts already joined: every melee fighter is pre-placed at the
     exact spot where they trade blows, so nobody charges in from the back line
     or bounces home after a swing. */
  function pairFighters() {
    if (!battle) return;
    const joinUp = (unit, target) => {
      const spot = engagementPoint(unit, target);
      unit.spotX = spot.x;
