/* CDP driver: verify pre-placed real-time duels, bubbles, labels, flows. */
const fs = require('fs');
const path = require('path');
const OUT = '/tmp/opencode/shots';
fs.mkdirSync(OUT, { recursive: true });
const URL_BASE = 'http://127.0.0.1:3003/index.html';
const W = parseInt(process.env.SHOT_W || '390', 10);
const H = parseInt(process.env.SHOT_H || '844', 10);
let ws, msgId = 0; const pending = new Map();

function send(method, params = {}) { return new Promise((resolve, reject) => { const id = ++msgId; pending.set(id, { resolve, reject }); ws.send(JSON.stringify({ id, method, params })); }); }
function waitLoad() { return new Promise(resolve => { const h = ev => { let m; try { m = JSON.parse(typeof ev.data === 'string' ? ev.data : ev); } catch { return; } if (m.method === 'Page.loadEventFired') { ws.removeEventListener('message', h); resolve(); } }; ws.addEventListener('message', h); }); }
const sleep = ms => new Promise(r => setTimeout(r, ms));

async function evalJs(expression) {
  const res = await send('Runtime.evaluate', { expression, returnByValue: true, awaitPromise: true });
  if (res.exceptionDetails) console.error('EVAL ERROR:', JSON.stringify(res.exceptionDetails).slice(0, 300));
  return res.result?.value;
}
async function shot(name, clip) {
  const params = { format: 'png' };
  if (clip) params.clip = { ...clip, scale: 2 };
  const data = await send('Page.captureScreenshot', params);
  fs.writeFileSync(path.join(OUT, `${name}.png`), Buffer.from(data.data, 'base64'));
  console.log('shot:', name);
}
async function click(sel) {
  const res = await evalJs(`(() => { const el = document.querySelector(${JSON.stringify(sel)}); if (!el) return 'missing'; el.click(); return 'ok'; })()`);
  console.log('click', sel, '->', res);
}

const probeExpr = `JSON.stringify([...document.querySelectorAll('.battle-unit')].map(el => {
  const cs = getComputedStyle(el);
  const hp = document.querySelector('[data-label-uid="' + el.dataset.uid + '"] .unit-health i');
  return { who: el.dataset.uid, x: Number(cs.getPropertyValue('--x')), y: Number(cs.getPropertyValue('--y')),
    hp: Math.round(parseFloat(hp?.style.width || '100')), cls: el.className.split(' ').filter(c => ['walking','strike-right','strike-left','dead','dying','hit'].includes(c)).join('|') };
}))`;

async function main() {
  const list = await (await fetch('http://127.0.0.1:9222/json')).json();
  const page = list.find(t => t.type === 'page');
  ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  ws.addEventListener('message', data => {
    let msg; try { msg = JSON.parse(typeof data.data === 'string' ? data.data : data); } catch { return; }
    if (msg.id && pending.has(msg.id)) { pending.get(msg.id).resolve(msg.result || {}); pending.delete(msg.id); }
    else if (msg.method === 'Runtime.consoleAPICalled' && ['error', 'warning'].includes(msg.params.type)) {
      console.log('CONSOLE', msg.params.type, msg.params.args.map(a => a.value ?? a.description).join(' ').slice(0, 250));
    } else if (msg.method === 'Runtime.exceptionThrown') {
      console.log('PAGE EXCEPTION:', JSON.stringify(msg.params.exceptionDetails.exception?.description || msg.params.exceptionDetails).slice(0, 250));
    }
  });
  await send('Page.enable'); await send('Runtime.enable');
  await send('Emulation.setDeviceMetricsOverride', { width: W, height: H, deviceScaleFactor: 2, mobile: true });

  const heroes = ['pip', 'nyx', 'bram', 'mica', 'sable'].slice(0, Number(process.env.SQUAD || 4));
  const levels = {}; heroes.forEach(h => { levels[h] = Number(process.env.LVL || 12); });
  const seed = {
    version: 2, coins: Number(process.env.COINS || 900), slots: heroes.length, heroes, levels,
    xp: Object.fromEntries(heroes.map(h => [h, 0])), cart: heroes,
    depth: Number(process.env.DEPTH || 6), bestDepth: 12, wins: 3, chests: 0, sound: false
  };
  const loaded = waitLoad();
  await send('Page.navigate', { url: 'http://127.0.0.1:3003/nope-404' });
  await loaded;
  await evalJs(`localStorage.clear(); localStorage.setItem('downbound.save.v2', ${JSON.stringify(JSON.stringify(seed))}); 'ok'`);
  const loaded2 = waitLoad();
  await send('Page.navigate', { url: URL_BASE });
  await loaded2;
  await sleep(800);
  await shot('r1-surface-bubbles');
  await click('[data-action="descend"]'); await sleep(850);
  await shot('r3-cave-bubbles');
  for (let i = 0; i < heroes.length; i++) {
    await click(`[data-cart-hero="${heroes[i]}"]`); await sleep(150);
    await click(`[data-pad="${i}"]`); await sleep(180);
  }
  await shot('r3b-cave-deployed');
  await click('[data-action="fight"]');
  await sleep(350);
  await shot('r4-fight-start');
  await sleep(500);
  await shot('r5-fighting');

  console.log('--- probe ---');
  for (let i = 0; i < 6; i++) {
    await sleep(420);
    console.log(i, await evalJs(probeExpr));
    if (i === 1) await shot('r6-duel');
    if (i === 2) { await click('[data-battle-hero]'); await sleep(320); await shot('r7-skill'); }
  }
  await sleep(900);
  await shot('r8-late');

  for (let i = 0; i < 50; i++) {
    if (await evalJs(`Boolean(document.querySelector('.result-overlay'))`)) break;
    await sleep(500);
  }
  await shot('r9-result');
  console.log('result:', (await evalJs(`document.querySelector('.result-card')?.innerText?.slice(0, 90) || 'none'`))?.replace(/\n/g, ' | '));
  await click('#resultCloseBtn'); await sleep(900);
  await shot('r10-surface-return');
  console.log('DIAG:', await evalJs(`JSON.stringify({ screens: [...document.querySelectorAll('.screen')].map(s => s.className), ghosts: document.querySelectorAll('.stage-ghost').length, overlay: document.querySelector('#overlayRoot')?.className })`));
  process.exit(0);
}
main().catch(err => { console.error('FATAL', err); process.exit(1); });

